-- D Mojo Stage — MySQL 8 / MariaDB 10.5+ schema (utf8mb4, InnoDB).
-- IDs are UUID strings generated by the app. Timestamps are UTC.
-- Access control is enforced in the server functions (src/lib/*.functions.ts).

CREATE TABLE users (
  id CHAR(36) NOT NULL PRIMARY KEY,
  email VARCHAR(255) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY users_email_uq (email)            -- utf8mb4_unicode_ci: case-insensitive
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE sessions (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  token_hash CHAR(64) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at DATETIME(3) NOT NULL,
  UNIQUE KEY sessions_token_uq (token_hash),
  KEY sessions_user_idx (user_id),
  KEY sessions_expires_idx (expires_at),
  CONSTRAINT sessions_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE user_roles (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  role ENUM('admin','editor','booking_manager','executive') NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY user_roles_uq (user_id, role),
  CONSTRAINT user_roles_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE events (
  id CHAR(36) NOT NULL PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  tagline VARCHAR(300) NULL,
  release_date DATE NULL,
  poster_url VARCHAR(500) NULL,
  trailer_url VARCHAR(500) NULL,
  synopsis TEXT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  event_type ENUM('movie','concert','live_show','theatre','festival','other') NOT NULL DEFAULT 'movie',
  booking_open TINYINT(1) NOT NULL DEFAULT 1,
  venue VARCHAR(200) NULL,
  city VARCHAR(100) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE halls (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(200) NOT NULL,
  city VARCHAR(100) NOT NULL,
  address VARCHAR(500) NULL,
  screen VARCHAR(100) NULL,
  show_time VARCHAR(100) NULL,
  facilities TEXT NULL,
  contact VARCHAR(200) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE hall_categories (
  id CHAR(36) NOT NULL PRIMARY KEY,
  hall_id CHAR(36) NOT NULL,
  name VARCHAR(100) NOT NULL,
  price INT NOT NULL,
  capacity INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY hall_categories_hall_idx (hall_id),
  CONSTRAINT hall_categories_hall_fk FOREIGN KEY (hall_id) REFERENCES halls(id) ON DELETE CASCADE,
  CONSTRAINT hall_categories_price_ck CHECK (price >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE executives (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  phone VARCHAR(30) NOT NULL,
  email VARCHAR(200) NULL,
  city VARCHAR(100) NULL,
  account_holder VARCHAR(120) NULL,
  bank_name VARCHAR(120) NULL,
  account_number VARCHAR(40) NULL,
  ifsc_code VARCHAR(20) NULL,
  aadhar_number VARCHAR(20) NULL,
  notes TEXT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  user_id CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY executives_user_uq (user_id),
  CONSTRAINT executives_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- MySQL has no sequences: booking numbers come from this one-row counter (see createBooking).
CREATE TABLE booking_counter (
  id TINYINT NOT NULL PRIMARY KEY,
  n BIGINT NOT NULL
) ENGINE=InnoDB;
INSERT INTO booking_counter (id, n) VALUES (1, 0);

CREATE TABLE bookings (
  id CHAR(36) NOT NULL PRIMARY KEY,
  booking_ref VARCHAR(30) NOT NULL,
  customer_name VARCHAR(100) NOT NULL,
  email VARCHAR(255) NULL,
  phone VARCHAR(20) NOT NULL,
  city VARCHAR(100) NOT NULL,
  event_id CHAR(36) NULL,
  hall_id CHAR(36) NULL,
  seat_category VARCHAR(100) NOT NULL,
  unit_price INT NOT NULL,
  num_seats INT NOT NULL,
  total_price INT NOT NULL,
  status VARCHAR(30) NOT NULL DEFAULT 'CONFIRMED',
  booking_source ENUM('self','executive') NOT NULL DEFAULT 'self',
  executive_id CHAR(36) NULL,
  payment_status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',
  payment_provider VARCHAR(30) NULL,
  payment_ref VARCHAR(100) NULL,
  paid_at DATETIME(3) NULL,
  ticket_code VARCHAR(100) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  UNIQUE KEY bookings_ref_uq (booking_ref),
  UNIQUE KEY bookings_ticket_uq (ticket_code),          -- many NULLs allowed
  KEY bookings_payment_status_idx (payment_status),
  KEY bookings_created_idx (created_at),
  KEY bookings_event_idx (event_id),
  KEY bookings_hall_idx (hall_id),
  KEY bookings_executive_idx (executive_id),
  CONSTRAINT bookings_event_fk FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL,
  CONSTRAINT bookings_hall_fk FOREIGN KEY (hall_id) REFERENCES halls(id) ON DELETE SET NULL,
  CONSTRAINT bookings_executive_fk FOREIGN KEY (executive_id) REFERENCES executives(id) ON DELETE SET NULL,
  CONSTRAINT bookings_seats_ck CHECK (num_seats > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE site_content (
  content_key VARCHAR(200) NOT NULL PRIMARY KEY,
  content_value TEXT NOT NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Page builder: data/position are the draft; published_* is what visitors see.
-- `data` holds JSON text (parsed in the app, so it works the same on MySQL and MariaDB).
CREATE TABLE page_blocks (
  id CHAR(36) NOT NULL PRIMARY KEY,
  page VARCHAR(100) NOT NULL,
  position INT NOT NULL DEFAULT 0,
  block_type VARCHAR(50) NOT NULL,
  data LONGTEXT NOT NULL,
  published_data LONGTEXT NULL,
  published_position INT NULL,
  draft_deleted TINYINT(1) NOT NULL DEFAULT 0,
  published_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY page_blocks_page_idx (page, position),
  KEY page_blocks_published_idx (page, published_position)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
